import math
from sys import stdin
input = stdin.readline

class Point:
	__slots__ = ['x', 'y', 'polarAngle']

	def __init__(self, x, y):
		self.x = x
		self.y = y
		self.polarAngle = 0.0

	def setPolarAngle(self, other):
		self.polarAngle = math.atan2(self.y - other.y, self.x - other.x)

	def direction(self, a, b, c):
		area = (b.x - a.x) * (c.y - a.y) - (c.x - a.x) * (b.y - a.y)
		if area < 0:
			return -1
		elif area > 0:
			return 1
		else:
			return 0

	def __eq__(self, other):
		return self.x == other.x and self.y == other.y

	def __ne__(self, x):
		return self.x != other.x or self.y != other.y

	def __hash__(self):
		return hash((self.x, self.y))

	def __repr__(self):
		return 'Point(' + str(self.x) + ',' + str(self.y) + ',' + '{:.2f}'.format(self.polarAngle) + ')'

def convexhull(points):
	points = sorted(points, key=lambda point: (point.y, point.x))
	points[0].polarAngle = 0.0
	for point in points[1:]:
		point.setPolarAngle(points[0])
	points = sorted(points, key=lambda point: point.polarAngle)
	hull = []
	hull.append(points[0])
	hull.append(points[1])
	for i in range(2, len(points)):
		top = hull.pop()
		while hull and top.direction(hull[-1], top, points[i]) <= 0:
			top = hull.pop()
		hull.append(top)
		hull.append(points[i])
	return hull

def sameside(line1, line2, p1, p2):
	return ((line1.y - line2.y) * (p1.x - line1.x) + (line2.x - line1.x) * (p1.y - line1.y)) * ((line1.y - line2.y) * (p2.x - line1.x) + (line2.x - line1.x) * (p2.y - line1.y)) > 0

def getmidpoints(points, N):
	hull1 = convexhull(points)
	sethull1 = set(hull1)
	N1 = len(hull1)
	centerX = sum((point.x for point in hull1)) / N1
	centerY = sum((point.y for point in hull1)) / N1
	center = Point(centerX, centerY)
	for i in range(N):
		if points[i] == center:
			points.pop(i)
			N -= 1
			break
	for point in points:
		point.setPolarAngle(center)
	points = sorted(points, key=lambda point: point.polarAngle)
	index_points = None
	for (i, point) in enumerate(points):
		if point in sethull1:
			index_points = i
			break
	index_hull1 = None
	for (i, point) in enumerate(hull1):
		if point == points[index_points]:
			index_hull1 = i
			break
	midpoints = set()
	for (i, point1) in enumerate(hull1):
		for point2 in [hull1[(i - 1) % N1], hull1[(i + 1) % N1]]:
			midpoints.add(Point(point1.x + point2.x, point1.y + point2.y))
	scope = [(index_hull1 - 1) % N1, index_hull1 % N1, (index_hull1 + 1) % N1]
	index_hull1_ini = index_hull1
	for twice in [1, 2]:
		index_hull1 = index_hull1_ini
		stop = 0
		for i in range(N):
			point1 = points[(index_points + i) % N]
			if point1 in sethull1:
				index_hull1 = (index_hull1 + 1) % N1
				scope.append((index_hull1 + 1) % N1)
				scope.pop(0)
				stop += 1
			else:
				for index2 in scope:
					point2 = hull1[index2]
					line1 = hull1[(index2 - 1) % N1]
					line2 = hull1[(index2 + 1) % N1]
					if sameside(line1, line2, point1, point2):
						midpoints.add(Point(point1.x + point2.x, point1.y + point2.y))
			if twice == 2 and stop > 2:
				break
	return midpoints

def solve(points, N):
	midpoints = getmidpoints(points, N)
	hull = convexhull(midpoints)
	return len(hull)
T = int(input().strip())
for problem in range(1, T + 1):
	N = int(input().strip())
	points = []
	for i in range(N):
		(x, y) = [int(x) for x in input().strip().split()]
		points.append(Point(x, y))
	print(solve(points, N))
